# Гл. 5, пакет G: G1 (крупные места, с правками автора: G1.5 — оригинал короче, «касса» → ящик под стойкой; G1.4 — без «и, и») + G2.
import pathlib
p = pathlib.Path("03-manuscript/arc-01/ch-05.md")
t = p.read_text(encoding="utf-8")
n = 0
def rep(old, new):
    global t, n
    c = t.count(old); assert c == 1, f"count={c}: {old[:70]!r}"
    t = t.replace(old, new); n += 1

